#pragma once
// Talk: conversations with squads are real Skyrim dialogue (ALifeTalk.esp, generated by tools/build_talk_esp.py). The plugin tells the
// dialogue system what situation the squad the player is looking at is in (two globals), shows a squad's spoken lines as ordinary
// subtitles, and reads which response the player chose from the engine's topic-info events. Nothing pauses the game or opens a
// menu the player did not ask for.
#include "ALife/Systems.h"

namespace ALife::Talk {
enum class Choice : std::uint8_t { None = 0, Pay, Poor, Refuse, Fight, Peace, Defy, News, Trade,
	                                Work, Accept, Decline, TurnIn, Deliver, Abandon,     // jobs (docs/TASKS.md): handled by Jobs
	                                Recruit, HireAsk, Hire1, Hire2, Follow, Wait, Move, HoldFire, Attack, Loot, NoLoot, Gear, Dismiss,   // companions (docs/COMPANIONS.md)
	                                Heal, WRob, Finish, Spare, RobGo, NoMercy };   // the wounded and the yielded (docs/WOUNDED.md): handled by Wounded

enum Mode : int { kNone = 0, kToll = 1, kChallenge = 2, kGreet = 3, kCompanion = 4,   // kCompanion: the player talks to a squad travelling with them
	              kWounded = 5, kYielded = 6 };                                   // a member who is down / who yielded (docs/WOUNDED.md)

void Init();                                   // kDataLoaded: read talk.ltx, resolve the globals and responses of ALifeTalk.esp
bool Ready();
void Reset();

// every tick: publish the situation of the squad under the crosshair (or keep it while a conversation is open), expire subtitles
void Pump(float a_dt);
void Publish(int a_mode, int a_toll);          // set the globals now (the debug activation uses this)
// Everything the dialogue reads about this squad in this mode: jobs (offers to a squad that greets you; the hand-in of a job squad
// travelling with you, mode kCompanion), companion topics, then the mode / toll globals. The crosshair pump and the debug activation
// both go through it, so they can never publish different situations (W3: the debug talk left the job state out in companion mode).
void PublishSquad(Group* a_g, int a_mode, int a_toll);
void Diagnose(RE::Actor* a_speaker);           // debug: which of the opening lines' conditions hold for this speaker right now
void Bind(RE::Actor* a);                        // puts the actor the player is about to talk to into the dialogue quest's Speaker alias
void Hold(float a_seconds);
float SecondsSinceConversation();                // real seconds since a conversation last closed (large at the start of a session)
void OpenBarter(RE::Actor* a_merchant);          // the barter menu on a squad member's own pack
void DebugChoose(const std::string& a_choice);  // debug builds: pick the offered topic whose prompt holds a_choice (pay, poor, refuse, fight, peace, defy, news; first if empty)                    // keep what was published for a moment (the engine reads it a frame after Activate)
bool InConversation();                         // a dialogue menu is open
std::uint64_t ConversationSquad();             // squad id of the speaker, 0 when none

std::string OpeningLine(const Group& a_g, int a_mode);                 // one of the squad's opening lines (stable per squad)
void Subtitle(RE::Actor* a_speaker, const std::string& a_text, float a_seconds = 4.5f);   // an ordinary spoken line, as a subtitle

void OnTopicInfo(const RE::TESTopicInfoEvent* a_event);                // the player chose a response / it finished
}

namespace ALife::Behavior {
void TalkSituation(const Group& a_g, int& a_mode, int& a_toll);       // what talking to this squad would be about right now
bool TalkPending(const Group& a_g);                                   // the squad has said something and is waiting for the player to talk
void OnTalk(Group& a_g, Talk::Choice a_choice, bool a_begin);         // the player chose a response (begin) / the reply was spoken (end)
}
